def _deep_update(left, right):
    result = dict(left)
    for key, value in right.items():
        if value is None:
            result.pop(key, None)
        elif isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = _deep_update(result[key], value)
        else:
            result[key] = value
    return result


def merge(base, environment, override):
    return _deep_update(_deep_update(base, environment), override)
